var scene=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();var game=UnityEngine.SceneManagement.SceneManager.GetSceneByPath("Assets/Scenes/GameScane.unity");bool opened=!game.isLoaded;if(opened)game=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/GameScane.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);
try{var ui=game.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<UİManager>(true)).First();var info=game.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<InfoPanelUI>(true)).First();var texts=game.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<UnityEngine.UI.Text>(true)).Where(x=>x.name=="GoldText"||x.name=="WaveText"||x==ui.preparationCountdownText).Select(x=>new{name=x.name,parent=x.transform.parent.name,rect=x.rectTransform.rect.ToString(),position=x.rectTransform.anchoredPosition.ToString(),parentRect=((RectTransform)x.transform.parent).rect.ToString()});return new{path=scene.path,playing=EditorApplication.isPlaying,dirty=scene.isDirty,texts=texts.ToArray(),speed=ui.speedButtons.Select(x=>new{name=x.name,parent=x.transform.parent.name,rect=((RectTransform)x.transform).rect.ToString(),position=((RectTransform)x.transform).anchoredPosition.ToString()}).ToArray(),info=new{root=info.name,panel=info.panel.name,parent=info.panel.parent.name,rect=info.panel.rect.ToString(),icon=info.icon.name,title=info.titleText.name,body=info.bodyText.name}};}finally{if(opened)UnityEditor.SceneManagement.EditorSceneManager.CloseScene(game,true);}
